import java.util.*;

public class Main {
    List<Integer> reverseKGroup(List<Integer> values, int k) {
        List<Integer> result = new ArrayList<>(values);
        int i = 0;
        while (i + k <= result.size()) {                                            // only reverse FULL groups of exactly k
            Collections.reverse(result.subList(i, i + k));
            i += k;
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(1, 2, 3, 4, 5);
        System.out.println(solution.reverseKGroup(values, 2));
    }
}

