vector<int> reverseKGroup(vector<int>& values, int k) {
    vector<int> result = values;
    int i = 0;
    while (i + k <= (int)result.size()) {                                          // only reverse FULL groups of exactly k
        reverse(result.begin() + i, result.begin() + i + k);
        i += k;
    }
    return result;
}

