#include <bits/stdc++.h>
using namespace std;

bool hasKNodes(ListNode* node, int k) {
    int count = 0;
    while (node && count < k) {
        node = node->next;
        count++;
    }
    return count == k;                                                                 // confirms at least k nodes remain from here
}

ListNode* reverseKGroup(ListNode* head, int k) {
    if (!hasKNodes(head, k)) return head;                                                 // fewer than k nodes left: leave this final group untouched

    ListNode *prev = nullptr, *curr = head;
    for (int i = 0; i < k; i++) {
        ListNode* next = curr->next;
        curr->next = prev;                                                                    // standard iterative reversal, but bounded to exactly k steps
        prev = curr;
        curr = next;
    }

    head->next = reverseKGroup(curr, k);                                                      // head is now this group's TAIL; link it to the next reversed group
    return prev;                                                                              // prev is now this group's new head
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
    ListNode* result = reverseKGroup(head, 2);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}
